/**
 * Open data behind OnCo: the sources we already pull from and the ones we could extend to.
 *
 * Rendered at /data-sources/ and mirrored in docs/DATA-SOURCES.md (the long form, with field mappings).
 * `status: "in use"` rows name the script or component that reads the source and how often it runs;
 * `status: "candidate"` rows carry an effort estimate and the risks to settle before a fetch script is written.
 *
 * Licence strings were read from each source's own terms page on LICENCES_CHECKED. Where the page could not be
 * fetched (bot-gated, JavaScript-only or 403) the string says "unverified" and records the best available statement
 * instead of guessing. Sources with academic-only, non-commercial or all-rights-reserved terms are listed so the
 * restriction is on record: OnCo links to them, it does not ingest them.
 */
export type DataSourceStatus = "in use" | "candidate";
export type Effort = "S" | "M" | "L";
export type Access = "REST API" | "GraphQL API" | "SPARQL" | "Bulk download" | "BigQuery" | "Web pages" | "Live in browser" | "Read by hand";

export type DataSource = {
  id: string;
  name: string;
  url: string;
  status: DataSourceStatus;
  /** Theme: what the source is about. */
  group: string;
  /** What it fuels (or would fuel) in OnCo: kinds, pages or checks. */
  fuels: string[];
  licence: string;
  /** True when a programmatic interface exists (REST, GraphQL, SPARQL, BigQuery or documented bulk files). */
  api: boolean;
  access: Access;
  /** S: a day, one script. M: a week, new fields or a page. L: new kinds, licences to negotiate or heavy parsing. */
  effort: Effort;
  notes: string;
  /** In use: the script or component and workflow that read it. */
  pipeline?: string;
  /** In use: refresh cadence. */
  cadence?: string;
  risks?: string;
  /** Id of the matching `collection` object, when the source also has a page of its own. */
  collection?: string;
};

export const LICENCES_CHECKED = "2026-09-09";
export const EFFORT_LABEL: Record<Effort, string> = { S: "Small", M: "Medium", L: "Large" };

